<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
if(empty($_SESSION['admin_id']))redirect('login.php');
$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'new');$url=trim((string)($_POST['meeting_url']??''));if(!in_array($status,['new','contacted','scheduled','completed','cancelled'],true))$error='Invalid status.';elseif($url!==''&&!filter_var($url,FILTER_VALIDATE_URL))$error='Enter a valid Zoom URL.';else{$q=$pdo->prepare('UPDATE zoom_requests SET status=?,meeting_url=? WHERE id=?');$q->execute([$status,$url?:null,$id]);redirect('zoom-meetings.php?saved=1');}}
$rows=$pdo->query('SELECT * FROM zoom_requests ORDER BY created_at DESC LIMIT 200')->fetchAll();
?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zoom requests — Hammad Graphic</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-dashboard"><main class="admin-container"><div class="admin-title-row"><div><div class="eyebrow">CLIENT MEETINGS</div><h1>Zoom <em>requests.</em></h1><p>Review requests, confirm a time, then paste the Zoom meeting link.</p></div><a class="button button-outline" href="index.php">Admin dashboard</a></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Meeting request updated.</div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><section class="admin-panel"><div class="table-scroll"><table class="admin-table"><thead><tr><th>Client / contact</th><th>Project</th><th>Preferred time (PKT)</th><th>Message</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['customer_name'])?></strong><br><?=e($r['email'])?><br><?=e($r['whatsapp'])?></td><td><?=e($r['project_topic'])?></td><td><?= $r['preferred_at']?e(date('d M Y, h:i A',strtotime($r['preferred_at']))):'Not specified' ?></td><td><?=e($r['message']??'—')?></td><td><form method="post" class="admin-form" style="min-width:220px;gap:8px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><?php foreach(['new','contacted','scheduled','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=$r['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><input type="url" name="meeting_url" placeholder="Zoom link after scheduling" value="<?=e($r['meeting_url']??'')?>"><button class="button button-primary">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="table-empty">No Zoom requests yet.</td></tr><?php endif;?></tbody></table></div></section><p class="admin-footnote">Zoom meetings are created in your Zoom account manually. This panel stores the request and the link you provide; it does not create Zoom meetings automatically.</p></main></body></html>